// Loads schema.json generated by `:crates:editor:schema` and provides helpers for defaults and type lookups.

export async function loadSchema(url = './schema.json') {
  const file = String(url ?? '').replace(/^\.\//, '')
  if (!/^[A-Za-z0-9_-]+\.json$/.test(file)) throw new Error('Invalid schema path')
  const response = await fetch(`./${encodeURIComponent(file)}`)
  if (!response.ok) throw new Error(`Failed to load ${file} (${response.status})`)
  return response.json()
}

export function typeDef(schema, name) {
  return schema?.types?.[name] ?? null
}

/** Builds a clean default JS object for a schema type (for "+ Add" buttons and new crates/animations). */
export function defaultForType(schema, fieldType) {
  if (!fieldType) return ''
  switch (fieldType.kind) {
    case 'string': return ''
    case 'int': return 0
    case 'number': return 0
    case 'boolean': return false
    case 'enum': return fieldType.values?.[0] ?? ''
    case 'list': return []
    case 'map': return {}
    case 'object': return defaultObject(schema, fieldType.type)
    default: return null
  }
}

export function defaultObject(schema, typeName) {
  const def = typeDef(schema, typeName)
  if (!def) return {}
  const obj = {}
  for (const field of def.fields) {
    if (field.default !== undefined) {
      obj[field.key] = structuredClone(field.default)
    } else if (field.nullable && !field.required) {
      obj[field.key] = null
    } else if (field.type.kind === 'object') {
      obj[field.key] = defaultObject(schema, field.type.type)
    } else {
      obj[field.key] = defaultForType(schema, field.type)
    }
  }
  return obj
}

